import { z } from 'zod';
import { isAbsoluteUrl } from '../../../../isAbsoluteUrl.js';
import { normalizeRelativePath } from '../../../../transforms/normalizeRelativePath.js';
export const mcpStringSchema = z
    .string()
    .trim()
    .nonempty()
    .refine((value) => !isAbsoluteUrl(value), {
    message: 'Must be a local path to an MCP definition JSON file.',
})
    .transform(normalizeRelativePath);
export const mcpObjSchema = z
    .object({
    source: mcpStringSchema,
    directory: z.string().trim().nonempty().transform(normalizeRelativePath).optional(),
})
    .strict();
export const mcpSchema = z
    .union([mcpStringSchema, mcpObjSchema])
    .describe('A local path to an MCP definition JSON file with tools and resources');
export const mcpNotSupportedSchema = z.never().optional();
